import React, { Ref } from 'react';
import { ChipIconContainer } from './ChipIcon.styles';
import { ChipIconProps } from './ChipIcon.types';

export const ChipIcon = React.forwardRef(
  ({ icon: Icon, ...restProps }: ChipIconProps, forwardedRef: Ref<HTMLDivElement>): JSX.Element => (
    <ChipIconContainer {...restProps} tabIndex={-1} ref={forwardedRef}>
      <Icon />
    </ChipIconContainer>
  )
);
